import{_ as e,o as r,c as n,ag as l}from"./chunks/framework.BcZEdlUI.js";const y=JSON.parse('{"title":"ADR-001: PySide6 vs Electron 作为桌面端 GUI 框架","description":"","frontmatter":{},"headers":[],"relativePath":"adr/001-pyside6-vs-electron.md","filePath":"adr/001-pyside6-vs-electron.md","lastUpdated":1781581339000}'),a={name:"adr/001-pyside6-vs-electron.md"};function s(i,t,o,d,g,c){return r(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="adr-001-pyside6-vs-electron-作为桌面端-gui-框架" tabindex="-1">ADR-001: PySide6 vs Electron 作为桌面端 GUI 框架 <a class="header-anchor" href="#adr-001-pyside6-vs-electron-作为桌面端-gui-框架" aria-label="Permalink to &quot;ADR-001: PySide6 vs Electron 作为桌面端 GUI 框架&quot;">​</a></h1><ul><li><strong>状态</strong>: ✅ Accepted</li><li><strong>日期</strong>: 2026-06-04</li><li><strong>作者</strong>: 架构团队</li><li><strong>关联版本</strong>: v1.0.0 ~ v2.0.0</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>SceneFab 作为 AI 影视解说创作工具，需要选择桌面端 GUI 框架。两个候选方案：</p><ol><li><strong>PySide6</strong>（Qt for Python）</li><li><strong>Electron</strong>（Chromium + Node.js）</li></ol><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><p>采用 <strong>PySide6</strong> 作为 SceneFab 桌面端 GUI 框架。</p><h2 id="权衡" tabindex="-1">权衡 <a class="header-anchor" href="#权衡" aria-label="Permalink to &quot;权衡&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th style="text-align:center;">PySide6</th><th style="text-align:center;">Electron</th></tr></thead><tbody><tr><td><strong>Python 生态集成</strong></td><td style="text-align:center;">✅ 原生</td><td style="text-align:center;">⚠️ 需 IPC 桥接</td></tr><tr><td><strong>本地文件 I/O 性能</strong></td><td style="text-align:center;">✅ 同步</td><td style="text-align:center;">⚠️ 异步 Promise</td></tr><tr><td><strong>FFmpeg 进程调用</strong></td><td style="text-align:center;">✅ subprocess</td><td style="text-align:center;">⚠️ child_process</td></tr><tr><td><strong>启动时间</strong></td><td style="text-align:center;">✅ ~1s</td><td style="text-align:center;">⚠️ ~3-5s</td></tr><tr><td><strong>打包体积</strong></td><td style="text-align:center;">✅ ~150MB</td><td style="text-align:center;">⚠️ ~200MB+</td></tr><tr><td><strong>视觉风格统一</strong></td><td style="text-align:center;">✅ Qt Style Sheets</td><td style="text-align:center;">✅ CSS</td></tr><tr><td><strong>跨平台</strong></td><td style="text-align:center;">✅ Win/Mac/Linux</td><td style="text-align:center;">✅ Win/Mac/Linux</td></tr><tr><td><strong>AI 模型本地运行</strong></td><td style="text-align:center;">✅ 直接调用 Python</td><td style="text-align:center;">❌ 需 Python sidecar</td></tr><tr><td><strong>开发迭代速度</strong></td><td style="text-align:center;">⚠️ 需重启</td><td style="text-align:center;">✅ 热重载</td></tr><tr><td><strong>社区生态</strong></td><td style="text-align:center;">⚠️ 较小</td><td style="text-align:center;">✅ 巨大</td></tr></tbody></table><h2 id="关键理由" tabindex="-1">关键理由 <a class="header-anchor" href="#关键理由" aria-label="Permalink to &quot;关键理由&quot;">​</a></h2><ol><li><strong>核心业务是 Python 生态</strong>：FFmpeg 进程、视频帧处理、LLM API 调用等全部在 Python 侧，使用 PySide6 避免 IPC 开销和序列化成本</li><li><strong>本地优先架构</strong>：视频/音频/帧数据全部在本地处理，PySide6 与 OpenCV/NumPy/PyTorch 等本地库无缝集成</li><li><strong>交付优势</strong>：PySide6 桌面包体积更轻，Electron + Chromium 包体积更大</li><li><strong>FFmpeg 集成</strong>：subprocess 同步调用更稳定，错误信息更易捕获</li></ol><h2 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h2><ul><li>✅ 享受 Python 生态的快速迭代</li><li>✅ FFmpeg/OpenCV/LLM 本地化零障碍</li><li>⚠️ UI 视觉风格需手动调 QSS（用 VitePress 文档站作参考）</li><li>⚠️ PySide6 学习曲线较陡（Signal/Slot、QThread、Model/View）</li></ul><h2 id="替代方案探索" tabindex="-1">替代方案探索 <a class="header-anchor" href="#替代方案探索" aria-label="Permalink to &quot;替代方案探索&quot;">​</a></h2><ul><li><strong>Webview (pywebview)</strong>: 保留 Python 后端 + Web 前端，但生态碎片化</li><li><strong>Tauri (Rust + WebView)</strong>: 体积更小但 Rust 生态不熟，且与 Python AI 库集成需 IPC</li></ul><h2 id="评审" tabindex="-1">评审 <a class="header-anchor" href="#评审" aria-label="Permalink to &quot;评审&quot;">​</a></h2><ul><li>决策已稳定 2+ 个大版本（v1.0.0 ~ v1.1.0），无回退计划</li></ul>',17)])])}const u=e(a,[["render",s]]);export{y as __pageData,u as default};
